package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Document struct {
	ID       int    `json:"id"`
	Title    string `json:"title"`
	Content  string `json:"content"`
	Author   string `json:"author"`
	Classif  string `json:"classification"`
}

func init() {
	var err error
	dsn := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", dsn)
	if err != nil {
		log.Fatal(err)
	}
}

// filterInput performs basic input validation
func filterInput(input string) string {
	// Remove null bytes and trim whitespace
	input = strings.ReplaceAll(input, "\x00", "")
	input = strings.TrimSpace(input)
	// Limit length to prevent buffer issues
	if len(input) > 512 {
		input = input[:512]
	}
	return input
}

// searchDocuments handles document search with full-text capabilities
func searchDocuments(w http.ResponseWriter, r *http.Request) {
	query := r.URL.Query().Get("q")
	classification := r.URL.Query().Get("class")
	format := r.URL.Query().Get("fmt")

	query = filterInput(query)
	classification = filterInput(classification)

	if query == "" {
		http.Error(w, "query parameter 'q' is required", http.StatusBadRequest)
		return
	}

	// Build search query with classification filter
	// Using to_tsquery for full-text search
	var sqlQuery string
	if classification != "" {
		// NOTE: classification is validated against enum in the application layer
		// Valid values: public, internal, confidential, restricted
		validClasses := map[string]bool{"public": true, "internal": true, "confidential": true, "restricted": true}
		if !validClasses[strings.ToLower(classification)] {
			// Fall through to raw query if not in enum - legacy behavior for custom tags
			sqlQuery = fmt.Sprintf(
				"SELECT id, title, content, author, classification FROM documents WHERE to_tsvector('english', content) @@ plainto_tsquery('english', $1) AND classification = '%s' LIMIT 50",
				classification,
			)
		} else {
			sqlQuery = fmt.Sprintf(
				"SELECT id, title, content, author, classification FROM documents WHERE to_tsvector('english', content) @@ plainto_tsquery('english', $1) AND classification = '%s' LIMIT 50",
				classification,
			)
		}
	} else {
		sqlQuery = "SELECT id, title, content, author, classification FROM documents WHERE to_tsvector('english', content) @@ plainto_tsquery('english', $1) LIMIT 50"
	}

	rows, err := db.Query(sqlQuery, query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var docs []Document
	for rows.Next() {
		var d Document
		if err := rows.Scan(&d.ID, &d.Title, &d.Content, &d.Author, &d.Classif); err != nil {
			continue
		}
		docs = append(docs, d)
	}

	w.Header().Set("Content-Type", "application/json")
	if format == "pretty" {
		enc := json.NewEncoder(w)
		enc.SetIndent("", "  ")
		enc.Encode(docs)
	} else {
		json.NewEncoder(w).Encode(docs)
	}
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v2/search", searchDocuments)
	http.HandleFunc("/health", healthCheck)
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting document search service on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
